 "people":[{"id":"P1","name":"\uC1A1\uC9C0\uC544","org":"\uC131\uACFC\uAD00\uB9AC (KPI)","scope":"team","role":"\uB2F4\uB2F9"},{"id":"P2","name":"\uC7AC\uBB34\uD300","org":"\uC7AC\uBB34","scope":"dept","role":"\uC8FC\uAC04 \uACE0\uC815 \uC2AC\uB86F"},{"id":"P3","name":"BI \uC194\uB8E8\uC158 \uC5C5\uCCB4","scope":"external","role":"\uAD50\uCCB4 \uC911","check":true}],
